3	 * Copyright 2022 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b neon_rot_ldr_at_top_sub
7	 * @parblock
8	 * ALU-dimension variant of neon_rot_ldr_at_top (2026-09-08).
9	 *
10	 * The 55-record dump campaign (docs/CORE179_PANIC_20260908_DUMP_CAMPAIGN_CRASH.md)
11	 * showed act corruption under all four ALU ops of the parent (add/eor/and/orr),
12	 * with DIFFERENT xor signatures per op: add = high-bit avalanche with low bytes
13	 * clean (carry-chain look), eor = few-bit flips concentrated in the low 24 bits.
14	 * This variant swaps the rotation to the SUB-family to test whether the
15	 * corruption signature follows the ALU class (carry-propagating vs pure
16	 * combinational) or is op-agnostic:
17	 *   i%4: sub / eor / bic / orn   (sub carries; eor/bic/orn are combinational)
18	 * Same skeleton otherwise: 3rd ldr at top + 2-src loads + rotating ALU +
19	 * back-to-back str/str. Golden precomputed in init; memcmp in cold path.
20	 * @endparblock
21	 */
22	
23	#include "sandstone.h"
24	#include <cstdint>
25	#include <cstring>
26	
27	#if defined(__aarch64__)
28	#include <arm_neon.h>
29	#endif
30	
31	#define NEON_ROT_LDR_AT_TOP_SUB_COUNT 1024
32	
33	struct NeonRotLdrAtTopSubData {
34	    uint64x2_t *srcA;
35	    uint64x2_t *srcB;
36	    uint64x2_t *scratch;
37	    uint64x2_t *expected;
38	};
39	
40	#if defined(__aarch64__)
41	
42	static inline void store_vec(void *addr, uint64x2_t val) {
43	    vst1q_u64(static_cast<uint64_t *>(addr), val);
44	}
45	
46	static inline uint64x2_t load_vec(const void *addr) {
47	    uint64x2_t res;
48	    __asm__ volatile ("ldr %q0, [%1]" : "=w"(res) : "r"(addr) : "memory");
49	    return res;
50	}
51	
52	#endif
53	
54	static int neon_rot_ldr_at_top_sub_init(struct test *test) {
55	    auto *data = static_cast<NeonRotLdrAtTopSubData *>(malloc(sizeof(NeonRotLdrAtTopSubData)));
56	    data->srcA = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_SUB_COUNT * sizeof(uint64x2_t)));
57	    data->srcB = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_SUB_COUNT * sizeof(uint64x2_t)));
58	    data->scratch = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_SUB_COUNT * sizeof(uint64x2_t)));
59	    data->expected = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_SUB_COUNT * sizeof(uint64x2_t)));
60	
61	    memset_random(data->srcA, NEON_ROT_LDR_AT_TOP_SUB_COUNT * sizeof(uint64x2_t));
62	    memset_random(data->srcB, NEON_ROT_LDR_AT_TOP_SUB_COUNT * sizeof(uint64x2_t));
63	    memset_random(data->scratch, NEON_ROT_LDR_AT_TOP_SUB_COUNT * sizeof(uint64x2_t));
64	
65	    /* golden: same rotating composition, computed on the same NEON units */
66	    for (int i = 0; i < NEON_ROT_LDR_AT_TOP_SUB_COUNT; i++) {
67	        switch (i % 4) {
68	            case 0: data->expected[i] = vsubq_u64(data->srcA[i], data->srcB[i]); break;
69	            case 1: data->expected[i] = veorq_u64(data->srcA[i], data->srcB[i]); break;
70	            case 2: data->expected[i] = vbicq_u64(data->srcA[i], data->srcB[i]); break;
71	            case 3: data->expected[i] = vornq_u64(data->srcA[i], data->srcB[i]); break;
72	        }
73	    }
74	
75	    test->data = data;
76	    return EXIT_SUCCESS;
77	}
78	
79	static int neon_rot_ldr_at_top_sub_run(struct test *test, int cpu) {
80	    auto *data = static_cast<NeonRotLdrAtTopSubData *>(test->data);
81	
82	    uint64x2_t *temp = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_SUB_COUNT * sizeof(uint64x2_t)));
83	    uint64x2_t *dst  = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_SUB_COUNT * sizeof(uint64x2_t)));
84	
85	    TEST_LOOP(test, 1 << 13) {
86	        for (int i = 0; i < NEON_ROT_LDR_AT_TOP_SUB_COUNT; i++) {
87	            uint64x2_t unused_x = load_vec(&data->scratch[i]);
88	            (void)unused_x;
89	
90	            uint64x2_t a = load_vec(&data->srcA[i]);
91	            uint64x2_t b = load_vec(&data->srcB[i]);
92	            uint64x2_t res;
93	
94	            switch (i % 4) {
95	                case 0: res = vsubq_u64(a, b); break;
96	                case 1: res = veorq_u64(a, b); break;
97	                case 2: res = vbicq_u64(a, b); break;
98	                case 3: res = vornq_u64(a, b); break;
99	            }
100	
101	            store_vec(&temp[i], res);
102	            store_vec(&dst[i], res);
103	        }
104	
105	        if (memcmp(dst, data->expected, NEON_ROT_LDR_AT_TOP_SUB_COUNT * sizeof(uint64x2_t)) != 0) {
106	            report_fail_msg("neon_rot_ldr_at_top_sub data miscompare");
107	        }
108	    }
109	
110	    free(dst);
111	    free(temp);
112	    return EXIT_SUCCESS;
113	}
114	
115	static int neon_rot_ldr_at_top_sub_cleanup(struct test *test) {
116	    auto *data = static_cast<NeonRotLdrAtTopSubData *>(test->data);
117	    if (data) {
118	        free(data->srcA);
119	        free(data->srcB);
120	        free(data->scratch);
121	        free(data->expected);
122	        free(data);
123	    }
124	    return EXIT_SUCCESS;
125	}
126	
127	DECLARE_TEST(neon_rot_ldr_at_top_sub, "ALU-dimension variant of ldr_at_top: rotation sub/eor/bic/orn (carry vs combinational signature test)")
128	    .test_init    = neon_rot_ldr_at_top_sub_init,
129	    .test_run     = neon_rot_ldr_at_top_sub_run,
130	    .test_cleanup = neon_rot_ldr_at_top_sub_cleanup,
131	    .quality_level = TEST_QUALITY_PROD,
132	END_DECLARE_TEST
