5	 *
6	 * @test @b neon_rot_ldr_at_top_mla
7	 * @parblock
8	 * Algebraic-dimension variant of neon_rot_ldr_at_top (2026-09-08).
9	 *
10	 * The parent's add/eor/and/orr are all simple 2-input ops. This variant
11	 * rotates through the multiply-accumulate family (i%4: mul / mla / mlsl /
12	 * eor-as-control) to test whether the SDC trigger tolerates the different
13	 * ALU latency/throughput structure of the Kunpeng 920 SIMD MAC pipe, and
14	 * whether corruption signatures change under accumulation chains:
15	 *   case 0: mulq_s32 then reinterpret   (pure multiply, long latency)
16	 *   case 1: mla-style: acc = add(mul)   (accumulate via explicit add)
17	 *   case 2: mls-style: acc = sub(mul)
18	 *   case 3: veor (parent control op, unchanged semantics)
19	 * 32-bit lanes chosen because mla/mls are s32-only on this ISA; sources
20	 * are built so products are exact (no overflow into sign bit), golden
21	 * precomputed in init on the same NEON units.
22	 * Same skeleton otherwise: 3rd ldr at top + 2-src loads + rotating ALU +
23	 * back-to-back str/str; memcmp in cold path.
24	 * @endparblock
25	 */
26	
27	#include "sandstone.h"
28	#include <cstdint>
29	#include <cstring>
30	
31	#if defined(__aarch64__)
32	#include <arm_neon.h>
33	#endif
34	
35	#define NEON_ROT_LDR_AT_TOP_MLA_COUNT 1024
36	
37	struct NeonRotLdrAtTopMlaData {
38	    uint32x4_t *srcA;
39	    uint32x4_t *srcB;
40	    uint32x4_t *scratch;
41	    uint32x4_t *expected;
42	};
43	
44	#if defined(__aarch64__)
45	
46	static inline void store_vec(void *addr, uint32x4_t val) {
47	    vst1q_u32(static_cast<uint32_t *>(addr), val);
48	}
49	
50	static inline uint32x4_t load_vec(const void *addr) {
51	    uint32x4_t res;
52	    __asm__ volatile ("ldr %q0, [%1]" : "=w"(res) : "r"(addr) : "memory");
53	    return res;
54	}
55	
56	/* keep every lane a small signed value so products never overflow s32 */
57	static inline uint32x4_t narrow_for_mul(uint32x4_t v) {
58	    return vandq_u32(v, vdupq_n_u32(0x0000ffff));   /* mask to signed 15-bit magnitude range */
59	}
60	
61	#endif
62	
63	static int neon_rot_ldr_at_top_mla_init(struct test *test) {
64	    auto *data = static_cast<NeonRotLdrAtTopMlaData *>(malloc(sizeof(NeonRotLdrAtTopMlaData)));
65	    data->srcA = static_cast<uint32x4_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_MLA_COUNT * sizeof(uint32x4_t)));
66	    data->srcB = static_cast<uint32x4_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_MLA_COUNT * sizeof(uint32x4_t)));
67	    data->scratch = static_cast<uint32x4_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_MLA_COUNT * sizeof(uint32x4_t)));
68	    data->expected = static_cast<uint32x4_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_MLA_COUNT * sizeof(uint32x4_t)));
69	
70	    memset_random(data->srcA, NEON_ROT_LDR_AT_TOP_MLA_COUNT * sizeof(uint32x4_t));
71	    memset_random(data->srcB, NEON_ROT_LDR_AT_TOP_MLA_COUNT * sizeof(uint32x4_t));
72	    memset_random(data->scratch, NEON_ROT_LDR_AT_TOP_MLA_COUNT * sizeof(uint32x4_t));
73	
74	    /* golden: same rotating composition, computed on the same NEON units */
75	    for (int i = 0; i < NEON_ROT_LDR_AT_TOP_MLA_COUNT; i++) {
76	        uint32x4_t a = narrow_for_mul(data->srcA[i]);
77	        uint32x4_t b = narrow_for_mul(data->srcB[i]);
78	        data->srcA[i] = a;   /* persist the narrowed sources so run-side
79	                              * recomputation sees identical inputs */
80	        data->srcB[i] = b;
81	        int32x4_t sa = vreinterpretq_s32_u32(a);
82	        int32x4_t sb = vreinterpretq_s32_u32(b);
83	        switch (i % 4) {
84	            case 0: data->expected[i] = vreinterpretq_u32_s32(vmulq_s32(sa, sb)); break;
85	            case 1: data->expected[i] = vreinterpretq_u32_s32(vaddq_s32(vmulq_s32(sa, sb), sa)); break;
86	            case 2: data->expected[i] = vreinterpretq_u32_s32(vsubq_s32(vmulq_s32(sa, sb), sb)); break;
87	            case 3: data->expected[i] = veorq_u32(a, b); break;
88	        }
89	    }
90	
91	    test->data = data;
92	    return EXIT_SUCCESS;
93	}
94	
95	static int neon_rot_ldr_at_top_mla_run(struct test *test, int cpu) {
96	    auto *data = static_cast<NeonRotLdrAtTopMlaData *>(test->data);
97	
98	    uint32x4_t *temp = static_cast<uint32x4_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_MLA_COUNT * sizeof(uint32x4_t)));
99	    uint32x4_t *dst  = static_cast<uint32x4_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_MLA_COUNT * sizeof(uint32x4_t)));
100	
101	    TEST_LOOP(test, 1 << 13) {
102	        for (int i = 0; i < NEON_ROT_LDR_AT_TOP_MLA_COUNT; i++) {
103	            uint32x4_t unused_x = load_vec(&data->scratch[i]);
104	            (void)unused_x;
105	
106	            uint32x4_t a = load_vec(&data->srcA[i]);
107	            uint32x4_t b = load_vec(&data->srcB[i]);
108	            uint32x4_t res;
109	
110	            int32x4_t sa = vreinterpretq_s32_u32(a);
111	            int32x4_t sb = vreinterpretq_s32_u32(b);
112	            switch (i % 4) {
113	                case 0: res = vreinterpretq_u32_s32(vmulq_s32(sa, sb)); break;
114	                case 1: res = vreinterpretq_u32_s32(vaddq_s32(vmulq_s32(sa, sb), sa)); break;
115	                case 2: res = vreinterpretq_u32_s32(vsubq_s32(vmulq_s32(sa, sb), sb)); break;
116	                case 3: res = veorq_u32(a, b); break;
117	            }
118	
119	            store_vec(&temp[i], res);
120	            store_vec(&dst[i], res);
121	        }
122	
123	        if (memcmp(dst, data->expected, NEON_ROT_LDR_AT_TOP_MLA_COUNT * sizeof(uint32x4_t)) != 0) {
124	            report_fail_msg("neon_rot_ldr_at_top_mla data miscompare");
125	        }
126	    }
127	
128	    free(dst);
129	    free(temp);
130	    return EXIT_SUCCESS;
131	}
132	
133	static int neon_rot_ldr_at_top_mla_cleanup(struct test *test) {
134	    auto *data = static_cast<NeonRotLdrAtTopMlaData *>(test->data);
135	    if (data) {
136	        free(data->srcA);
137	        free(data->srcB);
138	        free(data->scratch);
139	        free(data->expected);
140	        free(data);
141	    }
142	    return EXIT_SUCCESS;
143	}
144	
145	DECLARE_TEST(neon_rot_ldr_at_top_mla, "Algebraic variant of ldr_at_top: rotation mul/mla-style/mls-style/eor in s32 lanes (MAC pipe + accumulate chain signature test)")
146	    .test_init    = neon_rot_ldr_at_top_mla_init,
147	    .test_run     = neon_rot_ldr_at_top_mla_run,
148	    .test_cleanup = neon_rot_ldr_at_top_mla_cleanup,
