        }
        iter++;
    }

    free(dst);
    free(temp);
    return EXIT_SUCCESS;
}

static int neon_rot_ldr_at_top_rowmajor_dump_cleanup(struct test *test) {
    auto *data = static_cast<NeonRotLdrAtTopRowMajorDumpData *>(test->data);
    if (data) {
        if (data->dump_fd >= 0) close(data->dump_fd);
