56	#define NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT 1024
57	
58	struct NeonRotLdrAtTopStr3CheckallData {
59	    uint64x2_t *srcA;
60	    uint64x2_t *srcB;
61	    uint64x2_t *scratch;
62	    uint64x2_t *expected;
63	    int dump_fd;
64	};
65	
66	#pragma pack(push, 1)
67	struct neon_rot_ldr_at_top_str3_checkall_record {
68	    uint64_t timestamp_us;
69	    uint32_t cpu;
70	    uint32_t iteration;
71	    uint32_t sweep_dir;       /* 0=ascending 1=descending */
72	    uint32_t sweep_slot_mask; /* first-read memcmp result: bit0=temp bit1=junk bit2=dst */
73	    uint32_t index;           /* 0xFFFFFFFF = transient (sweep-level only, re-read clean) */
74	    uint32_t op;              /* 0=add 1=eor 2=and 3=orr (i%4); 0xFFFFFFFF for transient */
75	    uint32_t index_slot_mask; /* cold per-index re-read, same bit layout */
76	    uint32_t _pad;
77	    uint64_t srcA_lo, srcA_hi; /* cold re-read (load- vs ALU-error classification) */
78	    uint64_t srcB_lo, srcB_hi;
79	    uint64_t exp_lo, exp_hi;
80	    uint64_t temp_lo, temp_hi; /* per-slot actuals (cold re-read) */
81	    uint64_t junk_lo, junk_hi;
82	    uint64_t dst_lo, dst_hi;
83	};
