88	static inline void store_vec(void *addr, uint64x2_t val) {
89	    vst1q_u64(static_cast<uint64_t *>(addr), val);
90	}
91	
92	static inline uint64x2_t load_vec(const void *addr) {
93	    uint64x2_t res;
94	    __asm__ volatile ("ldr %q0, [%1]" : "=w"(res) : "r"(addr) : "memory");
95	    return res;
96	}
97	
98	/* cold-path helper: full-vector equality test */
99	static inline bool vec_eq(uint64x2_t x, uint64x2_t y) {
100	    uint64x2_t diffs = veorq_u64(x, y);
101	    uint64x2_t orred = vpaddq_u64(diffs, diffs);   /* fold lanes together */
102	    return vgetq_lane_u64(orred, 0) == 0 && vgetq_lane_u64(orred, 1) == 0;
103	}
104	
105	/* cold path only: noinline so the per-index scan can never be fused or
106	 * scheduled into the hot loop (tlbstress loop-fusion lesson) */
107	static void __attribute__((noinline)) str3_checkall_cold_scan(
108	        struct NeonRotLdrAtTopStr3CheckallData *data,
109	        uint64x2_t *temp, uint64x2_t *junk, uint64x2_t *dst,
110	        int cpu, uint32_t iter, bool ascending, uint32_t sweep_slot_mask)
111	{
112	    bool any_index = false;
113	
114	    for (int i = 0; i < NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT; i++) {
115	        const uint64x2_t exp = data->expected[i];
116	        const uint64x2_t t   = temp[i];
117	        const uint64x2_t j   = junk[i];
118	        const uint64x2_t d   = dst[i];
119	
120	        uint32_t m = 0;
121	        if (!vec_eq(t, exp)) m |= 1u << 0;
122	        if (!vec_eq(j, exp)) m |= 1u << 1;
123	        if (!vec_eq(d, exp)) m |= 1u << 2;
124	        if (m == 0)
125	            continue;
126	
127	        any_index = true;
128	        /* reread sources here (cold) to classify load- vs ALU-error */
129	        const uint64x2_t a = load_vec(&data->srcA[i]);
130	        const uint64x2_t b = load_vec(&data->srcB[i]);
131	
132	        log_error("neon_rot_ldr_at_top_str3_checkall: idx %u op %u dir %s cpu %u: "
133	                  "slot_mask=0x%x [s0=temp s1=junk s2=dst] "
134	                  "srcA=%016lx%016lx srcB=%016lx%016lx exp=%016lx%016lx "
135	                  "temp=%016lx%016lx junk=%016lx%016lx dst=%016lx%016lx",
136	                  (unsigned)i, (unsigned)(i % 4),
137	                  ascending ? "asc" : "desc",
138	                  (unsigned)device_info[cpu].cpu_number,
139	                  m,
140	                  vgetq_lane_u64(a,1), vgetq_lane_u64(a,0),
141	                  vgetq_lane_u64(b,1), vgetq_lane_u64(b,0),
142	                  vgetq_lane_u64(exp,1), vgetq_lane_u64(exp,0),
143	                  vgetq_lane_u64(t,1),  vgetq_lane_u64(t,0),
144	                  vgetq_lane_u64(j,1),  vgetq_lane_u64(j,0),
145	                  vgetq_lane_u64(d,1),  vgetq_lane_u64(d,0));
146	
147	        if (data->dump_fd >= 0) {
148	            struct timeval tv;
149	            gettimeofday(&tv, nullptr);
150	            struct neon_rot_ldr_at_top_str3_checkall_record rec = {
151	                .timestamp_us = (uint64_t)tv.tv_sec * 1000000ULL + (uint64_t)tv.tv_usec,
152	                .cpu = (uint32_t)device_info[cpu].cpu_number, /* cpu param is thread_num; translate to logical CPU */
153	                .iteration = iter,
154	                .sweep_dir = ascending ? 0u : 1u,
155	                .sweep_slot_mask = sweep_slot_mask,
156	                .index = (uint32_t)i,
157	                .op = (uint32_t)(i % 4),
158	                .index_slot_mask = m,
159	                ._pad = 0,
160	                .srcA_lo = vgetq_lane_u64(a, 0), .srcA_hi = vgetq_lane_u64(a, 1),
161	                .srcB_lo = vgetq_lane_u64(b, 0), .srcB_hi = vgetq_lane_u64(b, 1),
162	                .exp_lo = vgetq_lane_u64(exp, 0), .exp_hi = vgetq_lane_u64(exp, 1),
163	                .temp_lo = vgetq_lane_u64(t, 0), .temp_hi = vgetq_lane_u64(t, 1),
164	                .junk_lo = vgetq_lane_u64(j, 0), .junk_hi = vgetq_lane_u64(j, 1),
165	                .dst_lo = vgetq_lane_u64(d, 0), .dst_hi = vgetq_lane_u64(d, 1),
166	            };
167	            write(data->dump_fd, &rec, sizeof(rec));
168	        }
169	    }
170	
171	    if (!any_index) {
172	        /* sweep-level mismatch whose per-index re-read came back clean:
173	         * transient / self-scrubbed error -- still record it */
174	        log_error("neon_rot_ldr_at_top_str3_checkall: sweep slot_mask=0x%x but per-index re-read clean (transient), cpu %u iter %u dir %s",
175	                  sweep_slot_mask, (unsigned)device_info[cpu].cpu_number, iter,
176	                  ascending ? "asc" : "desc");
177	        if (data->dump_fd >= 0) {
178	            struct timeval tv;
179	            gettimeofday(&tv, nullptr);
180	            struct neon_rot_ldr_at_top_str3_checkall_record rec = {
181	                .timestamp_us = (uint64_t)tv.tv_sec * 1000000ULL + (uint64_t)tv.tv_usec,
182	                .cpu = (uint32_t)device_info[cpu].cpu_number,
183	                .iteration = iter,
184	                .sweep_dir = ascending ? 0u : 1u,
185	                .sweep_slot_mask = sweep_slot_mask,
186	                .index = 0xFFFFFFFFu,
187	                .op = 0xFFFFFFFFu,
188	                .index_slot_mask = 0,
189	                ._pad = 0,
190	                /* remaining fields zero: the mismatch did not survive the re-read */
191	            };
192	            write(data->dump_fd, &rec, sizeof(rec));
193	        }
194	    }
