199	static int neon_rot_ldr_at_top_str3_checkall_init(struct test *test) {
200	    auto *data = static_cast<NeonRotLdrAtTopStr3CheckallData *>(malloc(sizeof(NeonRotLdrAtTopStr3CheckallData)));
201	    data->srcA = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t)));
202	    data->srcB = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t)));
203	    data->scratch = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t)));
204	    data->expected = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t)));
205	
206	    memset_random(data->srcA, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t));
207	    memset_random(data->srcB, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t));
208	    memset_random(data->scratch, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t));
209	
210	    /* golden: same rotating composition, computed on the same NEON units */
211	    for (int i = 0; i < NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT; i++) {
212	        switch (i % 4) {
213	            case 0: data->expected[i] = vaddq_u64(data->srcA[i], data->srcB[i]); break;
214	            case 1: data->expected[i] = veorq_u64(data->srcA[i], data->srcB[i]); break;
215	            case 2: data->expected[i] = vandq_u64(data->srcA[i], data->srcB[i]); break;
216	            case 3: data->expected[i] = vorrq_u64(data->srcA[i], data->srcB[i]); break;
217	        }
218	    }
219	
220	    char path[256];
221	    snprintf(path, sizeof(path), "/var/tmp/neon_rot_ldr_at_top_str3_checkall_%d.bin", getpid());
222	    data->dump_fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
223	    if (data->dump_fd < 0) {
224	        log_error("neon_rot_ldr_at_top_str3_checkall: failed to open dump log %s", path);
225	    }
226	
227	    test->data = data;
228	    return EXIT_SUCCESS;
229	}
230	
231	static int neon_rot_ldr_at_top_str3_checkall_run(struct test *test, int cpu) {
232	    auto *data = static_cast<NeonRotLdrAtTopStr3CheckallData *>(test->data);
233	
234	    uint64x2_t *temp = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t)));
235	    uint64x2_t *dst  = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t)));
236	    uint64x2_t *junk = static_cast<uint64x2_t *>(aligned_alloc(64, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t)));
237	
238	    uint64_t sweep = 0;
239	    TEST_LOOP(test, 1 << 13) {
240	        const bool ascending = (sweep & 1) == 0;
241	        for (int n = 0; n < NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT; n++) {
242	            const int i = ascending ? n : (NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT - 1 - n);
243	
244	            uint64x2_t unused_x = load_vec(&data->scratch[i]);
245	            (void)unused_x;
246	
247	            uint64x2_t a = load_vec(&data->srcA[i]);
248	            uint64x2_t b = load_vec(&data->srcB[i]);
249	            uint64x2_t res;
250	
251	            switch (i % 4) {
252	                case 0: res = vaddq_u64(a, b); break;
253	                case 1: res = veorq_u64(a, b); break;
254	                case 2: res = vandq_u64(a, b); break;
255	                case 3: res = vorrq_u64(a, b); break;
256	            }
257	
258	            store_vec(&temp[i], res);
259	            store_vec(&junk[i], res);
260	            store_vec(&dst[i], res);
261	        }
262	        sweep++;
263	
264	        /* all three slots checked unconditionally -- temp-only and
265	         * junk-only errors must not be gated on dst (that gating is
266	         * exactly the parent's blind spot this variant exists to close) */
267	        uint32_t slot_mask = 0;
268	        if (memcmp(temp, data->expected, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t)) != 0) slot_mask |= 1u << 0;
269	        if (memcmp(junk, data->expected, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t)) != 0) slot_mask |= 1u << 1;
270	        if (memcmp(dst,  data->expected, NEON_ROT_LDR_AT_TOP_STR3_CHECKALL_COUNT * sizeof(uint64x2_t)) != 0) slot_mask |= 1u << 2;
271	        if (slot_mask != 0) {
272	            str3_checkall_cold_scan(data, temp, junk, dst,
273	                                    cpu, (uint32_t)(sweep - 1), ascending, slot_mask);
274	            report_fail_msg("neon_rot_ldr_at_top_str3_checkall store-slot miscompare: sweep slot_mask 0x%x (s0=temp s1=junk s2=dst; records in dump bin)", slot_mask);
275	        }
276	    }
277	
278	    free(dst);
279	    free(junk);
280	    free(temp);
281	    return EXIT_SUCCESS;
282	}
283	
284	static int neon_rot_ldr_at_top_str3_checkall_cleanup(struct test *test) {
285	    auto *data = static_cast<NeonRotLdrAtTopStr3CheckallData *>(test->data);
286	    if (data) {
287	        if (data->dump_fd >= 0) close(data->dump_fd);
288	        free(data->srcA);
289	        free(data->srcB);
290	        free(data->scratch);
291	        free(data->expected);
292	        free(data);
293	    }
294	    return EXIT_SUCCESS;
295	}
296	
297	DECLARE_TEST(neon_rot_ldr_at_top_str3_checkall, "Store-slot classification variant of str3: same hot loop (3 ldr + rot ALU + 3 str of same res to temp/junk/dst); per-sweep 3-way memcmp catches temp-only and junk-only errors; on fail records which store slot(s) mismatched (slot_mask 0b111=upstream load/ALU error, single-bit=that store's write path) with per-slot actuals for s0-vs-s1-vs-s2 rate comparison")
298	    .test_init    = neon_rot_ldr_at_top_str3_checkall_init,
299	    .test_run     = neon_rot_ldr_at_top_str3_checkall_run,
300	    .test_cleanup = neon_rot_ldr_at_top_str3_checkall_cleanup,
301	    .quality_level = TEST_QUALITY_PROD,
302	END_DECLARE_TEST
