69	#define K5FAR_COUNT 1024              /* elements (uint64x2_t) */
70	#define K5FAR_SRC_ELEMS (K5FAR_COUNT * 2)   /* interleaved buffer: 2 families */
71	#define K5FAR_DUMP_DIR "movbe_log/gps_rowmajor"   /* same classifier dir */
72	
73	#define K5FAR_MAGIC_A   0xA5A5ULL
74	#define K5FAR_MAGIC_B   0x5A5AULL
75	#define K5FAR_MAGIC_SCR 0x0F0FULL
76	
77	struct K5FarData {
78	    uint64x2_t *src;        /* interleaved: even elem = A-family, odd = B */
79	    uint64x2_t *scratch;
80	    uint64x2_t *expected;
81	};
82	
83	#if defined(__aarch64__)
84	
85	static inline void store_vec(void *addr, uint64x2_t val) {
86	    vst1q_u64(static_cast<uint64_t *>(addr), val);
87	}
88	
89	static inline uint64x2_t load_vec(const void *addr) {
90	    uint64x2_t res;
91	    __asm__ volatile ("ldr %q0, [%1]" : "=w"(res) : "r"(addr) : "memory");
92	    return res;
93	}
94	
95	#endif
96	
97	static inline uint64_t gps_tag(uint64_t magic, uint64_t byte_off, uint64_t gen) {
98	    return (magic                      << 48)
99	         | ((byte_off        & 0xFFFFULL) << 32)
100	         | ((~byte_off       & 0xFFFFULL) << 16)
101	         |  (gen             & 0xFFFFULL);
102	}
103	
104	static int k5far_init(struct test *test) {
105	    auto *data = static_cast<K5FarData *>(malloc(sizeof(K5FarData)));
106	    data->src     = static_cast<uint64x2_t *>(aligned_alloc(64, K5FAR_SRC_ELEMS * sizeof(uint64x2_t)));
107	    data->scratch = static_cast<uint64x2_t *>(aligned_alloc(64, K5FAR_COUNT * sizeof(uint64x2_t)));
108	    data->expected= static_cast<uint64x2_t *>(aligned_alloc(64, K5FAR_COUNT * sizeof(uint64x2_t)));
109	
110	    mkdir(K5FAR_DUMP_DIR, 0755);
111	
112	    /* Interleaved tagged fill — the ONLY functional delta vs the GPS
113	     * chassis.  Element 2*i: A-family; element 2*i+1: B-family.  The
114	     * byte_off field records the offset in the FULL interleaved buffer
115	     * so the classifier can resolve the address neighbour directly. */
116	    for (int e = 0; e < K5FAR_SRC_ELEMS; e++) {
117	        const uint64_t byte = static_cast<uint64_t>(e) * 16;
118	        const uint64_t magic = (e & 1) ? K5FAR_MAGIC_B : K5FAR_MAGIC_A;
119	        store_vec(&data->src[e], vcombine_u64(vcreate_u64(gps_tag(magic, byte + 0, 0)),
120	                                              vcreate_u64(gps_tag(magic, byte + 8, 0))));
121	    }
122	    for (int i = 0; i < K5FAR_COUNT; i++) {
123	        const uint64_t byte = static_cast<uint64_t>(i) * 16;
124	        store_vec(&data->scratch[i], vcombine_u64(vcreate_u64(gps_tag(K5FAR_MAGIC_SCR, byte + 0, 0)),
125	                                                  vcreate_u64(gps_tag(K5FAR_MAGIC_SCR, byte + 8, 0))));
126	    }
127	
128	    /* golden: same rotating composition on the same NEON units */
129	    for (int i = 0; i < K5FAR_COUNT; i++) {
130	        const uint64x2_t a = data->src[2 * i];
131	        const uint64x2_t b = data->src[2 * i + 1];
132	        switch (i % 4) {
133	            case 0: data->expected[i] = vaddq_u64(a, b); break;
134	            case 1: data->expected[i] = veorq_u64(a, b); break;
135	            case 2: data->expected[i] = vandq_u64(a, b); break;
136	            case 3: data->expected[i] = vorrq_u64(a, b); break;
137	        }
138	    }
139	
140	    test->data = data;
141	    return EXIT_SUCCESS;
142	}
143	
144	static int k5far_run(struct test *test, int cpu) {
145	    auto *data = static_cast<K5FarData *>(test->data);
146	
147	    uint64x2_t *temp = static_cast<uint64x2_t *>(aligned_alloc(64, K5FAR_COUNT * sizeof(uint64x2_t)));
148	    uint64x2_t *dst  = static_cast<uint64x2_t *>(aligned_alloc(64, K5FAR_COUNT * sizeof(uint64x2_t)));
149	
150	    uint64_t sweep = 0;
151	    TEST_LOOP(test, 1 << 13) {
152	        const bool ascending = (sweep & 1) == 0;
153	        for (int n = 0; n < K5FAR_COUNT; n++) {
154	            const int i = ascending ? n : (K5FAR_COUNT - 1 - n);
155	
156	            uint64x2_t unused_x = load_vec(&data->scratch[i]);
157	            (void)unused_x;
158	
159	            uint64x2_t a = load_vec(&data->src[2 * i]);
160	            uint64x2_t b = load_vec(&data->src[2 * i + 1]);
161	            uint64x2_t res;
162	
163	            switch (i % 4) {
164	                case 0: res = vaddq_u64(a, b); break;
165	                case 1: res = veorq_u64(a, b); break;
166	                case 2: res = vandq_u64(a, b); break;
167	                case 3: res = vorrq_u64(a, b); break;
168	            }
169	
170	            store_vec(&temp[i], res);
171	            store_vec(&dst[i], res);
172	        }
173	        sweep++;
174	
175	        if (memcmp(dst, data->expected, K5FAR_COUNT * sizeof(uint64x2_t)) != 0) {
176	            /* COLD path, gated by memcmp.  Five-buffer dump in the SAME
177	             * layout as the GPS chassis for classifier compatibility:
178	             * dst, expected, "srcA-view" (even elements), "srcB-view"
179	             * (odd elements), scratch.  Both views are materialised from
180	             * the interleaved buffer so the offline classifier can use
181	             * its existing A/B magic logic unchanged. */
182	            char path[256];
183	            snprintf(path, sizeof(path), "%s/k5far_fail_cpu%d_sweep%lu.bin", K5FAR_DUMP_DIR,
184	                     cpu, static_cast<unsigned long>(sweep));
185	            FILE *f = fopen(path, "wb");
186	            if (f) {
187	                /* materialise the two views (cold path only) */
188	                uint64x2_t *viewA = static_cast<uint64x2_t *>(aligned_alloc(64, K5FAR_COUNT * sizeof(uint64x2_t)));
189	                uint64x2_t *viewB = static_cast<uint64x2_t *>(aligned_alloc(64, K5FAR_COUNT * sizeof(uint64x2_t)));
190	                for (int i = 0; i < K5FAR_COUNT; i++) {
191	                    viewA[i] = data->src[2 * i];
192	                    viewB[i] = data->src[2 * i + 1];
193	                }
194	                fwrite(dst,        sizeof(uint64x2_t), K5FAR_COUNT, f);
195	                fwrite(data->expected, sizeof(uint64x2_t), K5FAR_COUNT, f);
196	                fwrite(viewA,      sizeof(uint64x2_t), K5FAR_COUNT, f);
197	                fwrite(viewB,      sizeof(uint64x2_t), K5FAR_COUNT, f);
198	                fwrite(data->scratch, sizeof(uint64x2_t), K5FAR_COUNT, f);
199	                fprintf(f, "k5far sweep=%lu\n", static_cast<unsigned long>(sweep));
200	                fclose(f);
201	                free(viewA);
202	                free(viewB);
203	            }
204	            report_fail_msg("neon_rot_ldr_at_top_rowmajor_k5far data miscompare");
205	        }
206	    }
207	
208	    free(dst);
209	    free(temp);
210	    return EXIT_SUCCESS;
211	}
212	
213	static int k5far_cleanup(struct test *test) {
214	    auto *data = static_cast<K5FarData *>(test->data);
215	    if (data) {
216	        free(data->src);
217	        free(data->scratch);
218	        free(data->expected);
219	        free(data);
220	    }
221	    return EXIT_SUCCESS;
222	}
223	
224	DECLARE_TEST(neon_rot_ldr_at_top_rowmajor_k5far, "K5 far-apart/interleaved dual source: srcA/srcB alternate elements in ONE address space (address-neighbour is always the other family) — E6 address-capture vs steering vs buffer-identity; same GPS tag + dump discipline")
225	    .test_init    = k5far_init,
226	    .test_run     = k5far_run,
227	    .test_cleanup = k5far_cleanup,
228	    .quality_level = TEST_QUALITY_PROD,
229	END_DECLARE_TEST
