1	/**
2	 * @copyright
3	 * Copyright 2022 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b neon_rot_ldr_at_top_rowmajor_k7p_zero / k7p_one / k7p_rand / k7p_hiham
7	 * @parblock
8	 * K7 pattern battery, 2x64b lane shape (2026-09-13,
9	 * docs/CORE179_READPATH_LOCALIZATION_CAMPAIGN_20260913.md §8).
10	 *
11	 * Real question: is the lane curve (2x64b=223/30min on the parent,
12	 * 4x32b=0, 16x8b=2) a PHYSICAL-lane effect or a pattern-activation
13	 * effect?  The first GPS round added a sharp clue: the op distribution
14	 * of corrupted words is heavily biased (orr 71% / and 23% / eor 5% /
15	 * add 1%) and the corrupted fields avoid all-0/all-1 byte segments —
16	 * the damage is pattern-SENSITIVE, not uniform.  This battery maps the
17	 * activation surface of the 2x64b path directly:
18	 *
19	 *   k7p_zero : all-zero operands (both sources)         -> activation floor
20	 *   k7p_one  : all-one operands                          -> complementary floor
21	 *   k7p_rand : natural random (memset_random)            -> parent chassis baseline
22	 *   k7p_hiham: high-Hamming tags (alternating 0x55/0xAA) -> maximum transition density
23	 *
24	 * All four share the SAME hot loop (family skeleton, add v0.2d shape,
25	 * i%4 rotation) — only the fill differs, mirroring the GPS chassis
26	 * design.  The rand cell doubles as the A-track natural-data reference
27	 * with dump capability (the parent rowmajor has no dump; this gives
28	 * the Phase 0.5 A/B comparison its A side).
29	 *
30	 * Pre-registered readouts:
31	 *   - zero/one cells ~0 fail while rand/hiham fail -> activation needs
32	 *     data diversity in the operand (pattern-gating confirmed; the
33	 *     lane question becomes "which patterns survive the 32b ALU shape");
34	 *   - all cells fail similarly -> pattern gating is weak in the 2x64b
35	 *     path, the 4x32b zero needs a different explanation (lane shape);
36	 *   - hiham >> rand -> transition density matters (physical coupling).
37	 *
38	 * NOTE on the all-zero/all-one cells: with constant operands the ALU
39	 * results are also constant, so a corrupted word is trivially
40	 * distinguishable; the golden is the constant expectation.  The GPS
41	 * tag structure is REPLACED by the pattern itself in zero/one/hiham
42	 * cells (tags would be uniform data, defeating the point); the rand
43	 * cell uses GPS tags so the field-substitution classifier works on it.
44	 * @endparblock
45	 */
46	
47	#include "sandstone.h"
48	#include <cstdint>
49	#include <cstring>
50	#include <cstdio>
51	#include <sys/stat.h>
52	
53	#if defined(__aarch64__)
54	#include <arm_neon.h>
55	#endif
56	
57	#define K7P_COUNT 1024
58	#define K7P_DUMP_DIR "movbe_log/gps_rowmajor"
59	
60	enum K7Pattern {
61	    P_ZERO,
62	    P_ONE,
63	    P_RAND_GPS,     /* GPS-tagged random = B-track shape */
64	    P_HIHAM,        /* 0x55AA alternating high-Hamming */
65	};
66	
67	struct K7PData {
68	    uint64x2_t *srcA;
69	    uint64x2_t *srcB;
70	    uint64x2_t *scratch;
71	    uint64x2_t *expected;
72	};
73	
74	#if defined(__aarch64__)
75	
76	static inline void store_vec(void *addr, uint64x2_t val) {
77	    vst1q_u64(static_cast<uint64_t *>(addr), val);
78	}
79	
80	static inline uint64x2_t load_vec(const void *addr) {
81	    uint64x2_t res;
82	    __asm__ volatile ("ldr %q0, [%1]" : "=w"(res) : "r"(addr) : "memory");
83	    return res;
84	}
85	
86	#endif
87	
88	static inline uint64_t gps_tag(uint64_t magic, uint64_t byte_off, uint64_t gen) {
89	    return (magic                      << 48)
90	         | ((byte_off        & 0xFFFFULL) << 32)
91	         | ((~byte_off       & 0xFFFFULL) << 16)
92	         |  (gen             & 0xFFFFULL);
93	}
94	
95	/* pattern fill: P_RAND_GPS keeps the GPS tag structure (classifier
96	 * works); the others are uniform patterns per the cell's purpose. */
97	static uint64_t pattern_word(enum K7Pattern p, int which, uint64_t byte_off) {
98	    switch (p) {
99	        case P_ZERO:     return 0x0000000000000000ULL;
100	        case P_ONE:      return 0xFFFFFFFFFFFFFFFFULL;
101	        case P_RAND_GPS: {
102	            const uint64_t magic = (which == 0) ? 0xA5A5ULL : ((which == 1) ? 0x5A5AULL : 0x0F0FULL);
103	            return gps_tag(magic, byte_off, 0);
104	        }
105	        case P_HIHAM: {
106	            /* high-Hamming with position info: alternate 0x55/0xAA per
107	             * byte so every adjacent byte pair differs in 8 bits, and
108	             * byte_off parity is recoverable offline */
109	            uint64_t w = 0;
110	            for (int b = 0; b < 8; b++) {
111	                const uint64_t nib = (((byte_off + static_cast<uint64_t>(b)) & 1) ? 0xAAULL : 0x55ULL);
112	                w |= (nib << (8 * b));
113	            }
114	            return w;
115	        }
116	    }
117	    return 0;
118	}
119	
120	static int k7p_init_common(struct test *test, enum K7Pattern p) {
121	    auto *data = static_cast<K7PData *>(malloc(sizeof(K7PData)));
122	    data->srcA    = static_cast<uint64x2_t *>(aligned_alloc(64, K7P_COUNT * sizeof(uint64x2_t)));
123	    data->srcB    = static_cast<uint64x2_t *>(aligned_alloc(64, K7P_COUNT * sizeof(uint64x2_t)));
124	    data->scratch = static_cast<uint64x2_t *>(aligned_alloc(64, K7P_COUNT * sizeof(uint64x2_t)));
125	    data->expected= static_cast<uint64x2_t *>(aligned_alloc(64, K7P_COUNT * sizeof(uint64x2_t)));
126	
127	    mkdir(K7P_DUMP_DIR, 0755);
128	
129	    for (int i = 0; i < K7P_COUNT; i++) {
130	        const uint64_t byte = static_cast<uint64_t>(i) * 16;
131	        store_vec(&data->srcA[i],    vcombine_u64(vcreate_u64(pattern_word(p, 0, byte + 0)),
132	                                                  vcreate_u64(pattern_word(p, 0, byte + 8))));
133	        store_vec(&data->srcB[i],    vcombine_u64(vcreate_u64(pattern_word(p, 1, byte + 0)),
134	                                                  vcreate_u64(pattern_word(p, 1, byte + 8))));
135	        store_vec(&data->scratch[i], vcombine_u64(vcreate_u64(pattern_word(p, 2, byte + 0)),
136	                                                  vcreate_u64(pattern_word(p, 2, byte + 8))));
137	    }
138	
139	    for (int i = 0; i < K7P_COUNT; i++) {
140	        switch (i % 4) {
141	            case 0: data->expected[i] = vaddq_u64(data->srcA[i], data->srcB[i]); break;
142	            case 1: data->expected[i] = veorq_u64(data->srcA[i], data->srcB[i]); break;
143	            case 2: data->expected[i] = vandq_u64(data->srcA[i], data->srcB[i]); break;
144	            case 3: data->expected[i] = vorrq_u64(data->srcA[i], data->srcB[i]); break;
145	        }
146	    }
147	
148	    test->data = data;
149	    return EXIT_SUCCESS;
150	}
